#include <iostream>
#include <string>
#include <unordered_map>
#include <mutex>
#include <chrono>
#include <future>
#include <vector>
#include <atomic>
#include <thread>
#include <functional>
#include <queue>
#include <condition_variable>

struct LoginAttempt {
    std::string username;
    std::string password_hash;
    std::string source_ip;
    std::chrono::steady_clock::time_point timestamp;
};

struct RateLimitEntry {
    std::atomic<int> attempts{0};
    std::chrono::steady_clock::time_point window_start;
    std::mutex entry_mutex;
};

class AuthService {
private:
    std::unordered_map<std::string, std::string> credential_store_;
    std::unordered_map<std::string, std::shared_ptr<RateLimitEntry>> rate_limits_;
    std::mutex rate_limit_map_mutex_;
    std::mutex credential_mutex_;

    static constexpr int MAX_ATTEMPTS_PER_WINDOW = 5;
    static constexpr auto WINDOW_DURATION = std::chrono::seconds(60);
    static constexpr auto LOCKOUT_DURATION = std::chrono::seconds(300);

    std::shared_ptr<RateLimitEntry> get_rate_limit_entry(const std::string& key) {
        std::lock_guard<std::mutex> lock(rate_limit_map_mutex_);
        auto it = rate_limits_.find(key);
        if (it == rate_limits_.end()) {
            auto entry = std::make_shared<RateLimitEntry>();
            entry->window_start = std::chrono::steady_clock::now();
            rate_limits_[key] = entry;
            return entry;
        }
        return it->second;
    }

    bool check_rate_limit(const std::string& key) {
        auto entry = get_rate_limit_entry(key);
        auto now = std::chrono::steady_clock::now();

        std::lock_guard<std::mutex> lock(entry->entry_mutex);
        auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(
            now - entry->window_start);

        if (elapsed >= WINDOW_DURATION) {
            entry->attempts.store(0, std::memory_order_relaxed);
            entry->window_start = now;
        }

        int current = entry->attempts.load(std::memory_order_relaxed);
        if (current >= MAX_ATTEMPTS_PER_WINDOW) {
            return false;
        }
        return true;
    }

    void record_attempt(const std::string& key) {
        auto entry = get_rate_limit_entry(key);
        entry->attempts.fetch_add(1, std::memory_order_relaxed);
    }

    bool verify_credentials(const std::string& username, const std::string& password_hash) {
        std::lock_guard<std::mutex> lock(credential_mutex_);
        auto it = credential_store_.find(username);
        if (it == credential_store_.end()) return false;
        return it->second == password_hash;
    }

public:
    AuthService() {
        credential_store_["admin"] = "5e884898da28047151d0e56f8dc6292773603d0d6aabbdd62a11ef721d1542d8";
        credential_store_["user1"] = "ef92b778bafe771e89245b89ecbc08a44a4e166c06659911881f383d4473e94f";
    }

    std::future<std::pair<bool, std::string>> authenticate_async(LoginAttempt attempt) {
        return std::async(std::launch::async, [this, attempt]() -> std::pair<bool, std::string> {
            std::string rate_key = attempt.source_ip;

            if (!check_rate_limit(rate_key)) {
                return {false, "Rate limited: too many attempts"};
            }

            // Simulate async credential verification delay
            std::this_thread::sleep_for(std::chrono::milliseconds(50));

            bool valid = verify_credentials(attempt.username, attempt.password_hash);

            // Record attempt AFTER verification completes
            record_attempt(rate_key);

            if (valid) {
                return {true, "Authentication successful"};
            }
            return {false, "Invalid credentials"};
        });
    }

    std::future<std::pair<bool, std::string>> authenticate_by_username_async(LoginAttempt attempt) {
        return std::async(std::launch::async, [this, attempt]() -> std::pair<bool, std::string> {
            std::string ip_key = attempt.source_ip;
            std::string user_key = "user:" + attempt.username;

            if (!check_rate_limit(ip_key)) {
                return {false, "IP rate limited"};
            }

            // Check per-user rate limit uses same window logic
            if (!check_rate_limit(user_key)) {
                return {false, "Account temporarily locked"};
            }

            std::this_thread::sleep_for(std::chrono::milliseconds(50));

            bool valid = verify_credentials(attempt.username, attempt.password_hash);

            record_attempt(ip_key);
            record_attempt(user_key);

            if (valid) {
                return {true, "Authentication successful"};
            }
            return {false, "Invalid credentials"};
        });
    }
};

int main() {
    AuthService service;

    // Simulate concurrent login attempts from credential stuffing attack
    std::vector<std::future<std::pair<bool, std::string>>> futures;

    // Attacker sends burst of requests from same IP
    for (int i = 0; i < 20; i++) {
        LoginAttempt attempt{
            "admin",
            "attempt_" + std::to_string(i),
            "192.168.1.100",
            std::chrono::steady_clock::now()
        };
        futures.push_back(service.authenticate_async(attempt));
    }

    int success = 0, blocked = 0, failed = 0;
    for (auto& f : futures) {
        auto [ok, msg] = f.get();
        if (msg.find("Rate limited") != std::string::npos) blocked++;
        else if (ok) success++;
        else failed++;
    }

    std::cout << "Results: " << success << " success, " 
              << failed << " failed, " << blocked << " blocked" << std::endl;
    return 0;
}
